import os
import subprocess
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
UPLOAD_DIR = '/tmp/configs'
os.makedirs(UPLOAD_DIR, exist_ok=True)

def validate_yaml_structure(data):
    """Validate that YAML has expected top-level keys."""
    required_keys = {'name', 'version', 'steps'}
    if not isinstance(data, dict):
        return False
    return required_keys.issubset(data.keys())

def execute_pipeline(config_path):
    """Execute a deployment pipeline from validated config."""
    with open(config_path, 'r') as f:
        config = yaml.safe_load(f)

    if not validate_yaml_structure(config):
        return {'error': 'Invalid pipeline structure'}, 400

    results = []
    for step in config.get('steps', []):
        step_type = step.get('type', '')
        if step_type == 'shell':
            cmd = step.get('command', '')
            # Basic blocklist for obviously dangerous commands
            blocked = ['rm -rf /', 'mkfs', 'dd if=']
            if any(b in cmd for b in blocked):
                results.append({'step': step.get('name'), 'status': 'blocked'})
                continue
            proc = subprocess.run(
                cmd, shell=True, capture_output=True, text=True, timeout=30
            )
            results.append({
                'step': step.get('name'),
                'stdout': proc.stdout,
                'stderr': proc.stderr,
                'returncode': proc.returncode
            })
        elif step_type == 'copy':
            src = step.get('src', '')
            dst = step.get('dst', '')
            proc = subprocess.run(
                ['cp', '-r', src, dst], capture_output=True, text=True
            )
            results.append({
                'step': step.get('name'),
                'returncode': proc.returncode
            })
        elif step_type == 'notify':
            results.append({'step': step.get('name'), 'status': 'notified'})

    return {'pipeline': config.get('name'), 'results': results}, 200

@app.route('/api/v1/pipeline/upload', methods=['POST'])
def upload_pipeline():
    """Upload and execute a pipeline configuration."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    f = request.files['file']
    if not f.filename.endswith(('.yml', '.yaml')):
        return jsonify({'error': 'Only YAML files accepted'}), 400

    filename = secure_filename(f.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)
    f.save(filepath)

    try:
        result, status = execute_pipeline(filepath)
        return jsonify(result), status
    finally:
        os.unlink(filepath)

@app.route('/api/v1/pipeline/status', methods=['GET'])
def pipeline_status():
    return jsonify({'status': 'ready', 'version': '2.4.1'}), 200

@app.route('/healthz')
def health():
    return 'ok', 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
